CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL, role text NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role_read ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE FUNCTION public.has_billing_role(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role='billing_admin') $$;
REVOKE ALL ON FUNCTION public.has_billing_role(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.has_billing_role(uuid) TO authenticated,service_role;
ALTER TABLE public.quote_requests ADD COLUMN billing_tax_id text, ADD COLUMN billing_address text, ADD COLUMN billing_email text;
COMMENT ON COLUMN public.quote_requests.invoice_number IS 'DEPRECATED: legacy reservation counter, not a fiscal invoice number. Fiscal numbers belong to billing_invoices.';
CREATE TABLE public.billing_orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reservation_id uuid REFERENCES public.quote_requests(id), is_test boolean NOT NULL DEFAULT true, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','confirmed','delivered','cancelled')), customer jsonb NOT NULL, lines jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.billing_orders TO authenticated;
GRANT ALL ON public.billing_orders TO service_role;
ALTER TABLE public.billing_orders ENABLE ROW LEVEL SECURITY;
CREATE POLICY billing_team_read ON public.billing_orders FOR SELECT TO authenticated USING(public.has_billing_role(auth.uid()));
CREATE TABLE public.billing_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES public.billing_orders(id), kind text NOT NULL CHECK(kind IN ('confirmation','advance','delivery','cancellation','refund')), operation_date date NOT NULL, amount numeric(12,2) NOT NULL DEFAULT 0, reason text NOT NULL DEFAULT '', actor uuid NOT NULL, idempotency_key uuid NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.billing_events TO authenticated;
GRANT ALL ON public.billing_events TO service_role;
ALTER TABLE public.billing_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY billing_team_read ON public.billing_events FOR SELECT TO authenticated USING(public.has_billing_role(auth.uid()));
CREATE TABLE public.billing_counters (is_test boolean NOT NULL, series text NOT NULL, fiscal_year integer NOT NULL, last_number integer NOT NULL DEFAULT 0, PRIMARY KEY(is_test,series,fiscal_year));
GRANT ALL ON public.billing_counters TO service_role;
ALTER TABLE public.billing_counters ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.billing_invoices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES public.billing_orders(id), event_id uuid NOT NULL UNIQUE REFERENCES public.billing_events(id), is_test boolean NOT NULL DEFAULT true, series text NOT NULL, fiscal_year integer NOT NULL, sequence_number integer NOT NULL, number text NOT NULL UNIQUE, kind text NOT NULL CHECK(kind IN ('advance','delivery','rectification')), issued_at timestamptz NOT NULL DEFAULT now(), operation_date date NOT NULL, original_invoice_id uuid REFERENCES public.billing_invoices(id), reason text NOT NULL DEFAULT '', snapshot jsonb NOT NULL, base numeric(12,2) NOT NULL, vat numeric(12,2) NOT NULL, total numeric(12,2) NOT NULL, actor uuid NOT NULL, UNIQUE(is_test,series,fiscal_year,sequence_number));
GRANT SELECT ON public.billing_invoices TO authenticated;
GRANT ALL ON public.billing_invoices TO service_role;
ALTER TABLE public.billing_invoices ENABLE ROW LEVEL SECURITY;
CREATE POLICY billing_team_read ON public.billing_invoices FOR SELECT TO authenticated USING(public.has_billing_role(auth.uid()));
CREATE TABLE public.billing_dispatch (invoice_id uuid PRIMARY KEY REFERENCES public.billing_invoices(id), pdf_path text, pdf_sha256 text, email_status text NOT NULL DEFAULT 'pending' CHECK(email_status IN ('pending','sent','failed')), email_error text, email_sent_at timestamptz, provider_id text, notion_status text NOT NULL DEFAULT 'pending' CHECK(notion_status IN ('pending','sent','failed')), notion_page_id text, notion_error text, lease_until timestamptz, attempts integer NOT NULL DEFAULT 0);
GRANT SELECT ON public.billing_dispatch TO authenticated;
GRANT ALL ON public.billing_dispatch TO service_role;
ALTER TABLE public.billing_dispatch ENABLE ROW LEVEL SECURITY;
CREATE POLICY billing_team_read ON public.billing_dispatch FOR SELECT TO authenticated USING(public.has_billing_role(auth.uid()));
CREATE TABLE public.billing_audit (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, actor uuid, action text NOT NULL, entity_id uuid, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.billing_audit TO authenticated;
GRANT ALL ON public.billing_audit TO service_role;
GRANT USAGE,SELECT ON SEQUENCE public.billing_audit_id_seq TO service_role;
ALTER TABLE public.billing_audit ENABLE ROW LEVEL SECURITY;
CREATE POLICY billing_team_read ON public.billing_audit FOR SELECT TO authenticated USING(public.has_billing_role(auth.uid()));
CREATE FUNCTION public.billing_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'billing_immutable'; END $$;
CREATE TRIGGER immutable_invoice BEFORE UPDATE OR DELETE ON public.billing_invoices FOR EACH ROW EXECUTE FUNCTION public.billing_immutable();
CREATE TRIGGER immutable_event BEFORE UPDATE OR DELETE ON public.billing_events FOR EACH ROW EXECUTE FUNCTION public.billing_immutable();
CREATE TRIGGER immutable_audit BEFORE UPDATE OR DELETE ON public.billing_audit FOR EACH ROW EXECUTE FUNCTION public.billing_immutable();
CREATE FUNCTION public.billing_record_event(p_order uuid,p_kind text,p_date date,p_amount numeric,p_reason text,p_key uuid,p_actor uuid) RETURNS uuid LANGUAGE plpgsql SET search_path=public AS $$ DECLARE o public.billing_orders; e public.billing_events; paid numeric; BEGIN
IF NOT public.has_billing_role(p_actor) THEN RAISE EXCEPTION 'forbidden'; END IF;
SELECT * INTO o FROM public.billing_orders WHERE id=p_order FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'order_missing'; END IF;
SELECT * INTO e FROM public.billing_events WHERE idempotency_key=p_key; IF FOUND THEN IF e.order_id<>p_order OR e.kind<>p_kind OR e.operation_date<>p_date OR e.amount<>p_amount OR e.reason<>p_reason THEN RAISE EXCEPTION 'idempotency_conflict'; END IF; RETURN e.id; END IF;
IF p_date>(now() AT TIME ZONE 'Europe/Madrid')::date THEN RAISE EXCEPTION 'future_operation'; END IF;
IF p_kind='confirmation' AND o.status<>'pending' THEN RAISE EXCEPTION 'invalid_state'; END IF;
IF p_kind IN ('advance','delivery') AND o.status<>'confirmed' THEN RAISE EXCEPTION 'invalid_state'; END IF;
IF p_kind='cancellation' AND o.status NOT IN ('pending','confirmed') THEN RAISE EXCEPTION 'invalid_state'; END IF;
IF p_kind='refund' AND o.status NOT IN ('cancelled','delivered') THEN RAISE EXCEPTION 'invalid_state'; END IF;
IF p_kind IN ('advance','refund') AND p_amount<=0 THEN RAISE EXCEPTION 'invalid_amount'; END IF;
IF p_kind NOT IN ('advance','refund') AND p_amount<>0 THEN RAISE EXCEPTION 'invalid_amount'; END IF;
SELECT COALESCE(sum(CASE WHEN kind='advance' THEN amount WHEN kind='refund' THEN -amount ELSE 0 END),0) INTO paid FROM public.billing_events WHERE order_id=p_order;
IF p_kind='refund' AND p_amount>paid THEN RAISE EXCEPTION 'refund_exceeds_payments'; END IF;
INSERT INTO public.billing_events(order_id,kind,operation_date,amount,reason,actor,idempotency_key) VALUES(p_order,p_kind,p_date,p_amount,p_reason,p_actor,p_key) RETURNING id INTO e.id;
UPDATE public.billing_orders SET status=CASE p_kind WHEN 'confirmation' THEN 'confirmed' WHEN 'delivery' THEN 'delivered' WHEN 'cancellation' THEN 'cancelled' ELSE status END WHERE id=p_order;
INSERT INTO public.billing_audit(actor,action,entity_id) VALUES(p_actor,p_kind,e.id); RETURN e.id; END $$;
REVOKE ALL ON FUNCTION public.billing_record_event(uuid,text,date,numeric,text,uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.billing_record_event(uuid,text,date,numeric,text,uuid,uuid) TO service_role;
CREATE FUNCTION public.billing_issue_test(p_event uuid,p_actor uuid,p_original uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SET search_path=public AS $$ DECLARE e public.billing_events; o public.billing_orders; inv public.billing_invoices; orig public.billing_invoices; yr integer; seq integer; ser text; b numeric:=0; v numeric:=0; tot numeric:=0; ratio numeric; line jsonb; out_lines jsonb:='[]'; id uuid; deductions jsonb:='[]'; BEGIN
IF NOT public.has_billing_role(p_actor) THEN RAISE EXCEPTION 'forbidden'; END IF;
SELECT * INTO e FROM public.billing_events WHERE id=p_event; IF NOT FOUND THEN RAISE EXCEPTION 'event_missing'; END IF;
SELECT * INTO o FROM public.billing_orders WHERE id=e.order_id FOR UPDATE;
IF NOT o.is_test THEN RAISE EXCEPTION 'production_invoicing_locked'; END IF;
SELECT * INTO inv FROM public.billing_invoices WHERE event_id=p_event; IF FOUND THEN RETURN inv.id; END IF;
IF e.kind NOT IN ('advance','delivery','refund') THEN RAISE EXCEPTION 'no_invoice_obligation'; END IF;
IF e.kind='refund' THEN
SELECT * INTO orig FROM public.billing_invoices WHERE id=p_original AND order_id=o.id AND kind<>'rectification'; IF NOT FOUND OR e.reason='' THEN RAISE EXCEPTION 'rectification_requires_original_and_reason'; END IF;
IF e.amount>orig.total-COALESCE((SELECT -sum(total) FROM public.billing_invoices WHERE original_invoice_id=orig.id),0) THEN RAISE EXCEPTION 'refund_exceeds_invoice'; END IF;
ratio:=-e.amount/orig.total; ser:='R';
FOR line IN SELECT value FROM jsonb_array_elements(orig.snapshot->'lines') LOOP out_lines:=out_lines||jsonb_build_array(line||jsonb_build_object('base',round((line->>'base')::numeric*ratio,2),'vat',round((line->>'vat')::numeric*ratio,2))); END LOOP;
ELSE
FOR line IN SELECT value FROM jsonb_array_elements(o.lines) LOOP tot:=tot+round((line->>'quantity')::numeric*(line->>'unitBase')::numeric*(1-(line->>'discountPct')::numeric/100),2)+round(round((line->>'quantity')::numeric*(line->>'unitBase')::numeric*(1-(line->>'discountPct')::numeric/100),2)*(line->>'vatRate')::numeric,2); END LOOP;
IF tot<=0 THEN RAISE EXCEPTION 'invalid_total'; END IF;
IF e.kind='advance' AND e.amount+COALESCE((SELECT sum(total) FROM public.billing_invoices WHERE order_id=o.id AND kind='advance'),0)>tot THEN RAISE EXCEPTION 'advance_exceeds_order'; END IF;
ratio:=CASE WHEN e.kind='advance' THEN e.amount/tot ELSE 1 END; ser:='F';
FOR line IN SELECT value FROM jsonb_array_elements(o.lines) LOOP out_lines:=out_lines||jsonb_build_array(line||jsonb_build_object('base',round(round((line->>'quantity')::numeric*(line->>'unitBase')::numeric*(1-(line->>'discountPct')::numeric/100),2)*ratio,2),'vat',round(round(round((line->>'quantity')::numeric*(line->>'unitBase')::numeric*(1-(line->>'discountPct')::numeric/100),2)*ratio,2)*(line->>'vatRate')::numeric,2))); END LOOP;
IF e.kind='delivery' THEN
IF EXISTS(SELECT 1 FROM public.billing_events ev WHERE ev.order_id=o.id AND ev.kind='advance' AND NOT EXISTS(SELECT 1 FROM public.billing_invoices i WHERE i.event_id=ev.id)) THEN RAISE EXCEPTION 'unbilled_advance'; END IF;
FOR inv IN SELECT * FROM public.billing_invoices WHERE order_id=o.id AND kind='advance' ORDER BY issued_at LOOP deductions:=deductions||jsonb_build_array(jsonb_build_object('number',inv.number,'total',inv.total)); FOR line IN SELECT value FROM jsonb_array_elements(inv.snapshot->'lines') LOOP out_lines:=out_lines||jsonb_build_array(line||jsonb_build_object('base',-(line->>'base')::numeric,'vat',-(line->>'vat')::numeric,'advanceNumber',inv.number)); END LOOP; END LOOP;
END IF; END IF;
FOR line IN SELECT value FROM jsonb_array_elements(out_lines) LOOP b:=b+(line->>'base')::numeric; v:=v+(line->>'vat')::numeric; END LOOP;
IF e.kind IN ('advance','refund') THEN v:=round(CASE WHEN e.kind='refund' THEN -e.amount ELSE e.amount END-b,2); END IF;
yr:=extract(year FROM now() AT TIME ZONE 'Europe/Madrid');
INSERT INTO public.billing_counters(is_test,series,fiscal_year,last_number) VALUES(true,ser,yr,1) ON CONFLICT(is_test,series,fiscal_year) DO UPDATE SET last_number=billing_counters.last_number+1 RETURNING last_number INTO seq;
INSERT INTO public.billing_invoices(order_id,event_id,series,fiscal_year,sequence_number,number,kind,operation_date,original_invoice_id,reason,snapshot,base,vat,total,actor) VALUES(o.id,e.id,ser,yr,seq,'TEST-'||ser||'-'||yr||'-'||lpad(seq::text,4,'0'),CASE WHEN e.kind='refund' THEN 'rectification' ELSE e.kind END,e.operation_date,p_original,e.reason,jsonb_build_object('customer',o.customer,'lines',out_lines,'advances',deductions,'issuer',jsonb_build_object('name','SANT JORDI SOLIDARI BARCELONA, S.L.','nif','B05857750','address','Carrer de Maria Llimona, 5, porta 5, 08019 Barcelona')),b,v,b+v,p_actor) RETURNING billing_invoices.id INTO id;
INSERT INTO public.billing_dispatch(invoice_id) VALUES(id); INSERT INTO public.billing_audit(actor,action,entity_id) VALUES(p_actor,'issue_test_invoice',id); RETURN id; END $$;
REVOKE ALL ON FUNCTION public.billing_issue_test(uuid,uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.billing_issue_test(uuid,uuid,uuid) TO service_role;